<?php partial('account_nav',['route'=>$route]); ?><section class="page-hero"><div><span class="eyebrow">YOUR LITTLE TREASURY</span><h1><?= e($title) ?></h1><p><?= t('Every change has a record. Every balance has a purpose.') ?></p></div><span class="page-hero-art"><?= icon('wallet') ?></span></section><div class="metric-grid section"><?php foreach (['balance'=>['Balance','wallet'],'points'=>['Points','sun'],'tokens'=>[$s->get('token_name'),'sparkles'],'commission'=>['Referral commission','gift'],'earnings'=>['Author earnings','chart']] as $currency=>$v): if (in_array($currency,['points','tokens'],true) && !$s->enabled($currency)) {continue;} if ($currency==='earnings' && !$s->enabled('creator_income') && !(int)$me['earnings']) {continue;} if ($currency==='commission' && !$s->enabled('affiliate')) {continue;} ?><div class="metric-card panel glass"><span class="metric-label"><?= icon($v[1]) ?><?= t($v[0]) ?></span><strong><?= \Chengyu\Services\Wallet::isMoney($currency)?money((int)$me[$currency]):number_format((int)$me[$currency]) ?></strong><small><?= t(\Chengyu\Services\Wallet::isMoney($currency)?'CNY / site ledger':'Site asset / no cash withdrawal') ?></small></div><?php endforeach ?></div><div class="two-column section"><section class="panel glass"><div class="section-heading"><h2><?= t('Add a little possibility') ?></h2><?= icon('plus') ?></div><?php $available=false; foreach (['epay','codepay'] as $gateway): if (!$s->enabled($gateway)) {continue;} $available=true; ?><?= form_start('topup','','stack') . intent() . hidden('gateway',$gateway) ?><h3><?= t($gateway==='epay'?'EPay-compatible checkout':'Legacy CodePay-compatible checkout') ?></h3><?php field('amount','Amount (CNY)','','number',['required'=>'required','step'=>'0.01','min'=>money((int)$s->get('topup_min')),'max'=>money((int)$s->get('topup_max'))]); $channels=[]; foreach (['alipay'=>'Alipay','wxpay'=>'WeChat Pay','qqpay'=>'QQ Pay'] as $key=>$name) {if ($s->get($gateway.'_'.$key)) {$channels[$key]=$name;}} select_field('method','Payment method',$channels); button('Continue to payment','full','lock'); ?></form><?php endforeach ?><?php if (!$available): ?><div class="alert info"><?= t('Online top-ups are not configured. A site administrator must connect and test a merchant gateway first.') ?></div><?php endif ?><p class="hint"><?= t('Only a verified payment callback credits your wallet. Returning from a payment page does not prove payment.') ?></p></section><section class="panel glass"><div class="section-heading"><h2><?= t('Exchange & redeem') ?></h2><?= icon('gift') ?></div><?php if ($s->enabled('points') || $s->enabled('tokens')): ?><?= form_start('exchange') . intent() ?><?php $currencies=[];foreach (['points','tokens'] as $c) {if ($s->enabled($c)) {$currencies[$c]=$c==='tokens'?$s->get('token_name'):'Points';}} select_field('currency','Receive asset',$currencies); field('amount','Spend balance (whole CNY)','','number',['min'=>'1','step'=>'1','required'=>'required']); button('Exchange now','secondary full','refresh'); ?><p class="hint">1 CNY = <?= (int)$s->get('points_rate') ?> <?= t('Points') ?> / <?= (int)$s->get('tokens_rate') ?> <?= e($s->get('token_name')) ?>. <?= t('Exchanges cannot be reversed automatically.') ?></p></form><?php endif ?><?php if ($s->enabled('vouchers')): ?><?= form_start('redeem') ?><?php field('code','Your redeem code','','text',['required'=>'required','autocomplete'=>'off']); button('Redeem code','secondary full','gift'); ?></form><?php endif ?></section></div>
<?php if ($s->enabled('transfers')): ?><section class="panel section"><?= form_start('transfer') . intent() ?><h2><?= t('Transfer site assets') ?></h2><div class="fields-grid"><?php field('recipient','Recipient username','','text',['required'=>'required']);select_field('currency','Currency',options(['balance','points','tokens']));field('amount','Amount','','number',['min'=>'0.01','step'=>'0.01','required'=>'required']);field('current_password','Current password','','password',['required'=>'required']); ?></div><?php button('Confirm transfer','','arrow'); ?><p class="hint"><?= t('Check the recipient carefully. Transfers are not automatically reversible.') ?></p></form></section><?php endif ?>
<?php if ($s->enabled('affiliate')): ?><section class="panel section"><h2><?= t('Invite good company') ?></h2><p><?= t('Your referral link') ?></p><div class="row wrap"><code><?= e($a->config['url'].'/index.php?r=register&ref='.rawurlencode($me['username'])) ?></code><button class="btn secondary small" data-copy="<?= e($a->config['url'].'/index.php?r=register&ref='.rawurlencode($me['username'])) ?>"><?= t('Copy') ?></button></div><p class="hint"><?= t('Eligible balance purchases earn the configured referral commission. Self-referrals are not supported.') ?></p></section><?php endif ?>
<?php if ($s->enabled('withdrawals')): ?><section class="panel section"><h2><?= t('Request an earnings payout') ?></h2><?= form_start('withdraw') . intent() ?><div class="fields-grid"><?php select_field('currency','Payout asset',options(['commission','earnings']));field('amount','Amount (CNY)','','number',['step'=>'0.01','min'=>money((int)$s->get('withdraw_min')),'required'=>'required']);field('current_password','Current password','','password',['required'=>'required']); ?></div><?php field('account','Payout account and recipient','','textarea',['required'=>'required']);button('Reserve earnings for review','','lock'); ?><p class="hint"><?= t('This reserves author earnings or referral commission for manual payout. Site balance, points and tokens are not withdrawable.') ?></p></form><?php foreach ($withdrawals as $w): ?><div class="row between"><span>#<?= (int)$w['id'] ?> / <?= e(price((int)$w['amount'],'balance')) ?></span><span class="pill"><?= t($w['status']) ?></span></div><?php endforeach ?></section><?php endif ?>
<section class="panel glass"><div class="section-heading"><h2><?= t('A clear record') ?></h2><span class="eyebrow">TRANSACTION HISTORY</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th><?= t('Date') ?></th><th><?= t('Details') ?></th><th><?= t('Change') ?></th><th><?= t('Balance after') ?></th></tr></thead><tbody><?php foreach ($ledger as $row): ?><tr><td><?= dt((int)$row['created_at'],'m.d H:i') ?></td><td><?= t($row['reason']) ?></td><td class="<?= (int)$row['delta']>0?'positive':'negative' ?>"><?= (int)$row['delta']>0?'+':'' ?><?= e(price((int)$row['delta'],$row['currency'])) ?></td><td><?= e(price((int)$row['balance_after'],$row['currency'])) ?></td></tr><?php endforeach ?></tbody></table></div><?php if (!$ledger) {empty_state('Your ledger is waiting for its first entry.','wallet');} ?><?php partial('pagination',['pagination'=>$pagination,'route'=>$route]); ?></section>
